//! `cargo-run_sk` — a real-time viewer with in-process hot-reload for StereoKit-rust projects (Linux, Windows &
//! macOS).
//!
//! The host keeps **one** StereoKit session alive (Simulator by default, OpenXR with `--xr`, offscreen with
//! `--offscreen`) and loads the plugin library of the project under development. Each time that library is rebuilt
//! (`cargo build --example main --features skc-shared` for this repository, or `cargo build --features skc-shared` for
//! an external project generated by `cargo-new_sk_rs_project`), the host swaps the plugin **without closing the
//! session**, and offers the developer's views (the `Test`s) in a selector window, with optional screenshots.
//!
//! The host and the plugin both link the same shared StereoKitC library (`libStereoKitC.so` on Linux,
//! `StereoKitC.dll` on Windows, `libStereoKitC.dylib` on macOS, feature `skc-shared`), so there is exactly ONE
//! StereoKit engine instance in the process: the plugin drives the host's session through it. The plugin is always
//! loaded from a copy under `target/run_sk/`, so the linker can always replace the original plugin file (a loaded
//! DLL cannot be overwritten on Windows).
//!
//! # Typical workflow (this repository)
//! ```bash
//! # terminal 1 - the viewer (Simulator by default)
//! cargo run_sk
//! ```
//! Fully automatic: by default the host also watches `src/`, `examples/` and `assets/`, and runs the build command
//! itself at startup and then on each change (`--no-build` to disable, `--build-cmd` to customize).
//!
//! With the Monado simulator runtime:
//! ```bash
//! XR_RUNTIME_JSON=/usr/share/openxr/1/openxr_monado.json \
//!     cargo run --bin cargo-run_sk --features skc-shared -- --xr
//! ```

#[cfg(not(any(any(target_os = "linux", target_os = "windows", target_os = "macos"), feature = "no-event-loop")))]
fn main() {
    eprintln!("cargo-run_sk: only supported on Linux, Windows and macOS for now");
}

#[cfg(all(any(target_os = "linux", target_os = "windows", target_os = "macos"), feature = "no-event-loop"))]
fn main() {
    eprintln!("cargo-run_sk: requires the default event loop framework (do not use the no-event-loop feature)");
}

#[cfg(all(any(target_os = "linux", target_os = "windows", target_os = "macos"), not(feature = "no-event-loop")))]
fn main() {
    imp::main();
}

#[cfg(all(any(target_os = "linux", target_os = "windows", target_os = "macos"), not(feature = "no-event-loop")))]
mod imp {
    use std::{
        ffi::{CStr, c_char, c_void},
        fs,
        io::Read,
        path::{Path, PathBuf},
        process::Command,
        rc::Rc,
        sync::mpsc::{Sender, TryRecvError, channel},
        thread::{self},
        time::{Duration, SystemTime},
    };

    use libloading::{Library, Symbol};
    use stereokit_rust::{
        framework::SkClosures,
        maths::{Pose, Quat, Vec2, Vec3},
        plugin_abi::{PluginViewInfo, SK_RUN_SK_ABI_VERSION},
        render::Renderer,
        sk::{AppMode, DepthMode, MainThreadToken, OriginMode, Sk, SkSettings},
        system::{Log, LogLevel},
        tools::build_tools::get_cargo_name,
        ui::Ui,
        util::Time,
    };

    pub const USAGE: &str = r#"Usage : cargo run_sk [OPTION]
    Real-time viewer for the project under development: keeps a single
    StereoKit session alive (Simulator or OpenXR) and hot-reloads the
    plugin library each time it is rebuilt.

        --simulator            : start in Simulator mode (default)
        --xr                   : start in OpenXR mode (no flatscreen fallback)
        --offscreen            : start without any display (CI / screenshots)
        --lib <path>           : plugin library to load
                                 (default: detected from the sources present:
                                 src/bin/main_<crate>.rs -> target/debug/<plugin>,
                                 examples/main*.rs -> target/debug/examples/<plugin>,
                                 else the first plugin file under target/debug/examples;
                                 plugin files are lib<name>.so on Linux,
                                 <name>.dll on Windows, lib<name>.dylib
                                 on macOS)
        --start <view name>    : view to select at start (name, or substring)
        --watch <secs>         : plugin library watch period, 0 disables (default 0.5)
        --build-cmd <command>  : build command run at startup and on source change.
                                 Default derived from the project layout (with the
                                 example name found in examples/ for this repo):
                                 "cargo build --example <name> --features skc-shared"
                                 or "cargo build --features skc-shared"
        --no-build             : don't watch sources / don't auto-build
        --test [N steps]       : run N steps (default 1000), screenshot the
                                 active view then exit
        --list                 : print the views of the plugin and exit
        --fullscreen           : ask the desktop window to start fullscreen
        -h | --help            : display this help

    Examples:
        cargo run_sk 
        cargo run_sk --xr --start Tex1
        cargo run_sk --offscreen --test 120 --start Ui1"#;

    // ------------------------------------------------------------------
    // Plugin loading
    // ------------------------------------------------------------------

    type FnU32 = unsafe extern "C" fn() -> u32;
    type FnCChar = unsafe extern "C" fn() -> *const c_char;
    type FnViewInfo = unsafe extern "C" fn(u32, *mut PluginViewInfo) -> u32;
    type FnSkPtr = unsafe extern "C" fn(*mut c_void) -> u32;
    type FnSkTokenPtr = unsafe extern "C" fn(*mut c_void, *mut c_void) -> u32;
    type FnIndex = unsafe extern "C" fn(u32) -> u32;

    /// One view of the plugin.
    struct View {
        name: String,
        has_screenshot: bool,
    }

    /// A successfully loaded (and possibly begun) plugin.
    struct Plugin {
        /// The loaded library: kept alive exactly as long as the fn
        /// pointers below are used.
        lib: Library,
        views: Vec<View>,
        select_fn: FnIndex,
        step_fn: FnSkTokenPtr,
        end_fn: FnU32,
    }

    impl Plugin {
        fn select(&self, index: u32) -> u32 {
            // SAFETY: `plugin_abi` contract, called on the main thread.
            unsafe { (self.select_fn)(index) }
        }

        fn step(&self, sk: *mut c_void, token: *mut c_void) -> u32 {
            // SAFETY: `plugin_abi` contract, called on the main thread.
            unsafe { (self.step_fn)(sk, token) }
        }

        fn end(&self) -> u32 {
            // SAFETY: `plugin_abi` contract, called on the main thread.
            unsafe { (self.end_fn)() }
        }
    }

    fn missing(symbol: &'static str) -> impl Fn(libloading::Error) -> String {
        move |err| format!("plugin has no symbol {symbol}: {err}")
    }

    /// Copies `src` to a unique file then loads it, checks the ABI and crate
    /// versions, reads the view list and eventually calls `begin`.
    /// * `sk` - the host `Sk` pointer, or `None` for a `--list` style inspection.
    fn load_plugin(sk: Option<*mut c_void>, src: &Path, copy_counter: &mut u32) -> Result<Plugin, String> {
        // Copy the freshly built plugin library to a unique name: cargo (and the Windows linker, which cannot
        // overwrite a loaded DLL) can then always replace the original file while we keep the previous plugin loaded.
        let copy_dir = Path::new("target/run_sk");
        fs::create_dir_all(copy_dir).map_err(|e| format!("cannot create {}: {e}", copy_dir.display()))?;
        let copy = copy_dir.join(format!("plugin-{copy_counter}.{}", plugin_ext()));
        *copy_counter += 1;
        fs::copy(src, &copy).map_err(|e| format!("cannot copy {} to {}: {e}", src.display(), copy.display()))?;

        // SAFETY: the symbols below follow the `stereokit_rust::plugin_abi` contract.
        unsafe {
            let lib = Library::new(&copy).map_err(|e| format!("cannot load {} (dlopen/LoadLibrary): {e}", copy.display()))?;

            let version: Symbol<FnU32> = lib.get(b"sk_run_sk_version").map_err(missing("sk_run_sk_version"))?;
            if version() != SK_RUN_SK_ABI_VERSION {
                return Err(format!(
                    "plugin ABI version {} does not match host ABI {}",
                    version(),
                    SK_RUN_SK_ABI_VERSION
                ));
            }

            let crate_version: Symbol<FnCChar> =
                lib.get(b"sk_run_sk_crate_version").map_err(missing("sk_run_sk_crate_version"))?;
            // SAFETY: the plugin returns a pointer to a static nul-terminated string.
            let plugin_version = CStr::from_ptr(crate_version()).to_string_lossy().into_owned();
            if plugin_version != env!("CARGO_PKG_VERSION") {
                return Err(format!(
                    "plugin was built with stereokit-rust {plugin_version} but the host uses {}: rebuild both sides from the same source",
                    env!("CARGO_PKG_VERSION")
                ));
            }

            let views_count: Symbol<FnU32> =
                lib.get(b"sk_run_sk_views_count").map_err(missing("sk_run_sk_views_count"))?;
            let view_info: Symbol<FnViewInfo> =
                lib.get(b"sk_run_sk_view_info").map_err(missing("sk_run_sk_view_info"))?;

            let count = views_count();
            let mut views = Vec::with_capacity(count as usize);
            for index in 0..count {
                let mut info = PluginViewInfo::new("", false);
                let status = view_info(index, &mut info);
                if status != 0 {
                    return Err(format!("sk_run_sk_view_info({index}) failed with status {status}"));
                }
                views.push(View { name: info.name(), has_screenshot: info.has_screenshot != 0 });
            }

            let begin: Symbol<FnSkPtr> = lib.get(b"sk_run_sk_begin").map_err(missing("sk_run_sk_begin"))?;
            let select: Symbol<FnIndex> = lib.get(b"sk_run_sk_select").map_err(missing("sk_run_sk_select"))?;
            let step: Symbol<FnSkTokenPtr> = lib.get(b"sk_run_sk_step").map_err(missing("sk_run_sk_step"))?;
            let end: Symbol<FnU32> = lib.get(b"sk_run_sk_end").map_err(missing("sk_run_sk_end"))?;

            // Copy the fn pointers out of the Symbols (they borrow `lib`) before
            // moving `lib` into the Plugin: sound because `Plugin` keeps `lib`
            // loaded for exactly as long as the pointers are used.
            let (begin, select, step, end) = (*begin, *select, *step, *end);

            if let Some(sk) = sk {
                let status = begin(sk);
                if status != 0 {
                    return Err(format!("sk_run_sk_begin failed with status {status}"));
                }
            }

            Ok(Plugin { lib, views, select_fn: select, step_fn: step, end_fn: end })
        }
    }

    fn find_view(views: &[View], name: &str) -> Option<usize> {
        views
            .iter()
            .position(|view| view.name == name)
            .or_else(|| views.iter().position(|view| view.name.eq_ignore_ascii_case(name)))
            .or_else(|| {
                let lower = name.to_lowercase();
                views.iter().position(|view| view.name.to_lowercase().contains(&lower))
            })
    }

    // ------------------------------------------------------------------
    // Background watchers
    // ------------------------------------------------------------------

    /// (mtime, size, head-hash) of a file. Cargo always rewrites the whole
    /// plugin file, so this is enough to detect a new build.
    type Fingerprint = Option<(SystemTime, u64, u64)>;

    fn fingerprint(path: &Path) -> Fingerprint {
        let meta = fs::metadata(path).ok()?;
        let mtime = meta.modified().ok()?;
        let size = meta.len();
        let mut head = 0u64;
        if let Ok(mut file) = fs::File::open(path) {
            let mut buffer = [0u8; 4096];
            if let Ok(n) = file.read(&mut buffer) {
                for chunk in buffer[..n].chunks(8) {
                    let mut bytes = [0u8; 8];
                    bytes[..chunk.len()].copy_from_slice(chunk);
                    head = head.wrapping_mul(31).wrapping_add(u64::from_le_bytes(bytes));
                }
            }
        }
        Some((mtime, size, head))
    }

    /// Messages sent by the background watcher threads to the main loop.
    enum HostMsg {
        /// The watched plugin library changed and is stable.
        LibChanged,
        /// A source change was detected, the build command is starting.
        BuildStarted,
        /// The build command finished.
        BuildFinished { ok: bool, tail: String },
    }

    /// Polls the plugin library and reports a `LibChanged` each time a NEW stable version appears (two consecutive
    /// identical samples: cargo may still be writing the file on the first one).
    fn watch_lib(path: PathBuf, period: Duration, sender: Sender<HostMsg>) {
        let mut candidate = fingerprint(&path);
        let mut stable = candidate;
        loop {
            thread::sleep(period);
            let current = fingerprint(&path);
            if current == candidate && current != stable {
                stable = current;
                sender.send(HostMsg::LibChanged).ok();
            }
            candidate = current;
        }
    }

    /// The paths scanned by the auto-build watcher.
    fn watch_roots() -> Vec<PathBuf> {
        ["src", "examples", "assets", "shaders_src", "Cargo.toml", "build.rs"]
            .into_iter()
            .map(PathBuf::from)
            .filter(|path| path.exists())
            .collect()
    }

    /// The name of the `examples/main*.rs`  (e.g. "main" for `examples/main.rs`, "main_pc" for `examples/main_pc.rs`),
    /// if any. The exact `examples/main.rs` wins over the other `main_*.rs` files.
    fn find_example_source_name() -> Option<String> {
        let examples_dir = PathBuf::from("examples");
        if !examples_dir.is_dir() {
            return None;
        }
        // Prefer the exact examples/main.rs.
        if examples_dir.join("main.rs").is_file() {
            return Some("main".to_string());
        }
        // Otherwise the first examples/main_*.rs.
        if let Ok(entries) = fs::read_dir(&examples_dir) {
            for entry in entries.flatten() {
                let path = entry.path();
                if let Some(file) = path.to_str() {
                    let name = file.rsplit('/').next().unwrap_or_default();
                    if name.starts_with("main_") {
                        if let Some(stem) = name.strip_suffix(".rs") {
                            return Some(stem.to_string());
                        }
                    }
                }
            }
        }
        None
    }

    /// The plugin library file extension of the current platform: `so` on Linux, `dll` on Windows, `dylib` on macOS.
    fn plugin_ext() -> &'static str {
        if cfg!(target_os = "windows") {
            "dll"
        } else if cfg!(target_os = "macos") {
            "dylib"
        } else {
            "so"
        }
    }

    /// The plugin library file name of the current platform: `lib<name>.so` on Linux, `<name>.dll` on Windows (no
    /// `lib` prefix), `lib<name>.dylib` on macOS.
    fn plugin_file(name: &str) -> String {
        if cfg!(target_os = "windows") {
            format!("{name}.dll")
        } else if cfg!(target_os = "macos") {
            format!("lib{name}.dylib")
        } else {
            format!("lib{name}.so")
        }
    }

    /// The default plugin library path, guessed from the layout of the current
    /// directory (source files present, not build artifacts):
    /// 1. `src/bin/main_<crate>.rs` exists -> a `cargo-new_sk_rs_project` project,
    ///    its plugin is `target/debug/<plugin of the crate>` (e.g. `libsk_project.so`
    ///    on Linux / `sk_project.dll` on Windows for the project `sk_project`),
    /// 2. `examples/main*.rs` exists -> the StereoKit-rust repository itself, its
    ///    plugin is `target/debug/examples/<plugin of the example>` (e.g.
    ///    `libmain_pc.so` / `main_pc.dll` for `examples/main_pc.rs`),
    /// 3. fallback: the first plugin file under `target/debug/examples/` (e.g.
    ///    cargo hashed copies), then the plugin of `examples/main.rs`.
    fn default_lib_path() -> PathBuf {
        // 1 - a project generated by cargo-new_sk_rs_project
        if let Ok(name) = get_cargo_name() {
            let lib_name = name.replace(['-'], "_");
            if PathBuf::from(format!("src/bin/main_{lib_name}.rs")).exists() {
                return PathBuf::from(format!("target/debug/{}", plugin_file(&lib_name)));
            }
        }
        // 2 - the StereoKit-rust repository itself
        if let Some(example) = find_example_source_name() {
            return PathBuf::from(format!("target/debug/examples/{}", plugin_file(&example)));
        }
        // 3 - fallback: whatever is already built under target/debug/examples
        if let Ok(entries) = fs::read_dir(&PathBuf::from("target/debug/examples")) {
            for entry in entries.flatten() {
                let path = entry.path();
                if let Some(extension) = path.extension() {
                    if extension == plugin_ext() {
                        return PathBuf::from(path);
                    }
                }
            }
        }
        PathBuf::from(format!("target/debug/examples/{}", plugin_file("main")))
    }

    /// The build command producing the plugin at `lib_path`, derived from the same
    /// layout probing as [`default_lib_path`] (so it integrates the example name
    /// found in `examples/`):
    /// - for this repository: `cargo build --example <name> --features skc-shared`,
    /// - otherwise: `cargo build --features skc-shared`.
    fn default_build_cmd(lib_path: &Path) -> String {
        if lib_path.components().any(|component| component.as_os_str() == "examples") {
            let example = find_example_source_name().unwrap_or_else(|| "main".to_string());
            format!("cargo build --example {example} --features skc-shared")
        } else {
            "cargo build --features skc-shared".to_string()
        }
    }

    /// Sum of the modification times of everything under `roots`.
    fn scan(roots: &[PathBuf]) -> u64 {
        fn visit(path: &Path, acc: &mut u64, depth: usize) {
            if depth > 6 {
                return;
            }
            let Ok(meta) = fs::metadata(path) else {
                return;
            };
            if meta.is_file() {
                if let Ok(mtime) = meta.modified()
                    && let Ok(since_epoch) = mtime.duration_since(SystemTime::UNIX_EPOCH)
                {
                    *acc = acc.wrapping_add(since_epoch.as_nanos() as u64);
                }
            } else if let Ok(entries) = fs::read_dir(path) {
                for entry in entries.flatten() {
                    visit(&entry.path(), acc, depth + 1);
                }
            }
        }
        let mut acc = 0u64;
        for root in roots {
            visit(root, &mut acc, 0);
        }
        acc
    }

    /// Runs the build command once (`sh -c <cmd>` on Linux, `cmd /C <cmd>` on Windows) and reports the outcome to
    /// the main loop. Build errors are reported but never fatal: the dev viewer keeps the last working plugin loaded.
    fn run_build(build_cmd: &str, sender: &Sender<HostMsg>) {
        sender.send(HostMsg::BuildStarted).ok();
        #[cfg(target_os = "windows")]
        let mut shell = Command::new("cmd");
        #[cfg(target_os = "windows")]
        shell.arg("/C");
        #[cfg(not(target_os = "windows"))]
        let mut shell = Command::new("sh");
        #[cfg(not(target_os = "windows"))]
        shell.arg("-c");
        match shell.arg(&build_cmd).output() {
            Ok(output) => {
                let ok = output.status.success();
                let tail = String::from_utf8_lossy(&output.stderr)
                    .lines()
                    .rev()
                    .take(8)
                    .collect::<Vec<_>>()
                    .into_iter()
                    .rev()
                    .collect::<Vec<_>>()
                    .join("\n");
                sender.send(HostMsg::BuildFinished { ok, tail }).ok();
            }
            Err(err) => {
                sender
                    .send(HostMsg::BuildFinished { ok: false, tail: format!("cannot run build command: {err}") })
                    .ok();
            }
        }
    }

    /// Watches the sources, and each time they settle down runs the build
    /// command (`sh -c` on Linux, `cmd /C` on Windows). The build (derived from the project layout, or the
    /// one passed with `--build-cmd`) is also run once at startup, so a fresh
    /// project gets built before the viewer needs its plugin. The rebuilt plugin
    /// library is then picked up by [`watch_lib`].
    fn watch_sources_and_build(roots: Vec<PathBuf>, debounce: Duration, build_cmd: String, sender: Sender<HostMsg>) {
        // Build once at startup: the plugin library may not exist yet.
        run_build(&build_cmd, &sender);
        let mut state = scan(&roots);
        loop {
            thread::sleep(Duration::from_millis(400));
            let mut current = scan(&roots);
            if current == state {
                continue;
            }
            // Debounce: wait for the sources to be quiet (an edit or a cargo
            // run touches many files).
            loop {
                thread::sleep(debounce);
                let again = scan(&roots);
                if again == current {
                    break;
                }
                current = again;
            }
            state = current;
            run_build(&build_cmd, &sender);
        }
    }

    /// Saves a screenshot of the current viewpoint as
    /// `screenshots/run_sk_<view>.jpeg`.
    fn capture_screenshot(view_name: &str) {
        fs::create_dir_all("screenshots").ok();
        let snake = view_name.to_lowercase().replace([' ', '/'], "_");
        let file = format!("screenshots/run_sk_{snake}.jpeg");
        Log::info(format!("cargo-run_sk: capturing {file}"));
        Renderer::screenshot(
            &file,
            90,
            Pose::look_at(Vec3::new(0.0, 0.4, -1.6), Vec3::new(0.0, 0.1, 0.0)),
            1280,
            720,
            Some(90.0),
        );
    }

    // ------------------------------------------------------------------
    // main
    // ------------------------------------------------------------------

    pub fn main() {
        //---- First the command line (style of the other cargo-* binaries)
        let mut fullscreen = false;
        let mut xr = false;
        let mut offscreen = false;
        let mut list = false;
        let mut no_build = false;
        let mut start_test = String::new();
        let mut lib_path = default_lib_path();
        let mut watch_secs = 0.5f32;
        let mut build_cmd: Option<String> = None;
        let mut test_steps: u32 = 0;

        let argv: Vec<String> = std::env::args().skip(1).collect();
        let mut index = 0;
        while let Some(arg) = argv.get(index).cloned() {
            index += 1;
            match &arg[..] {
                // cargo may pass the subcommand name itself as first argument
                "run_sk" => {}
                "--simulator" => {}
                "--xr" => xr = true,
                "--offscreen" => offscreen = true,
                "--fullscreen" => fullscreen = true,
                "--list" => list = true,
                "--no-build" => no_build = true,
                "--lib" => match argv.get(index) {
                    Some(value) if !value.starts_with('-') => {
                        lib_path = PathBuf::from(value);
                        index += 1;
                    }
                    _ => panic!("No value specified for parameter --lib."),
                },
                "--start" => match argv.get(index) {
                    Some(value) if !value.starts_with('-') => {
                        start_test = value.clone();
                        index += 1;
                    }
                    _ => panic!("No value specified for parameter --start."),
                },
                "--watch" => match argv.get(index) {
                    Some(value) if !value.starts_with('-') => {
                        watch_secs = value.parse().unwrap_or_else(|_| panic!("--watch expects a number of seconds"));
                        index += 1;
                    }
                    _ => panic!("No value specified for parameter --watch."),
                },
                "--build-cmd" => match argv.get(index) {
                    Some(value) if !value.starts_with('-') => {
                        build_cmd = Some(value.clone());
                        index += 1;
                    }
                    _ => panic!("No value specified for parameter --build-cmd."),
                },
                "--test" => {
                    test_steps = 1000;
                    if let Some(value) = argv.get(index)
                        && !value.starts_with('-')
                    {
                        test_steps = value.parse().unwrap_or_else(|_| panic!("--test expects a number of steps"));
                        index += 1;
                    }
                }
                "-h" | "--help" => println!("{USAGE}"),
                _ => {
                    if arg.starts_with('-') {
                        println!("Unknown argument {arg}");
                    } else {
                        println!("Unknown positional argument {arg}");
                    }
                    println!("{USAGE}");
                    return;
                }
            }
        }

        //---- --list: load the plugin without any StereoKit session
        if list {
            let mut copy_counter = 0;
            return match load_plugin(None, &lib_path, &mut copy_counter) {
                Ok(plugin) => {
                    println!("cargo-run_sk: {} views in {}", plugin.views.len(), lib_path.display());
                    for (index, view) in plugin.views.iter().enumerate() {
                        println!(
                            "  [{index:2}] {} {}",
                            view.name,
                            if view.has_screenshot { "[screenshot]" } else { "" }
                        );
                    }
                }
                Err(err) => {
                    eprintln!("cargo-run_sk: {err}");
                    std::process::exit(1);
                }
            };
        }

        //---- Initialize StereoKit with a single session for the whole dev cycle
        let mut settings = SkSettings::default();
        settings
            .app_name("cargo-run_sk")
            .origin(OriginMode::Floor)
            .depth_mode(DepthMode::D32)
            .omit_empty_frames(true)
            .log_filter(LogLevel::Diagnostic)
            .fullscreen(fullscreen);
        if xr {
            settings.mode(AppMode::XR).no_flatscreen_fallback(true);
        } else if offscreen {
            settings.mode(AppMode::Offscreen);
        } else {
            settings.mode(AppMode::Simulator);
        }
        let sk = settings.init().expect("cargo-run_sk: cannot initialize StereoKit");

        //---- Background watchers
        let build_cmd = build_cmd.unwrap_or_else(|| default_build_cmd(&lib_path));
        let (sender, receiver) = channel::<HostMsg>();
        if watch_secs > 0.0 {
            let sender = sender.clone();
            let path = lib_path.clone();
            thread::spawn(move || watch_lib(path, Duration::from_secs_f32(watch_secs), sender));
        }
        if !no_build {
            let sender = sender.clone();
            let roots = watch_roots();
            let cmd = build_cmd.clone();
            thread::spawn(move || watch_sources_and_build(roots, Duration::from_secs(1), cmd, sender));
        }
        Log::info(format!("cargo-run_sk: plugin {:#?}, build command: {build_cmd}", lib_path.display()));

        //---- Main loop state (shared between the step and shutdown closures)
        let plugin_cell = Rc::new(std::cell::RefCell::new(None::<Plugin>));
        let plugin_cell_for_shutdown = plugin_cell.clone();

        // Everything below is captured by the FnMut step closure.
        let mut loaded_fp = fingerprint(&lib_path);
        let mut zombie: Option<Library> = None; // end()ed, unloaded on the NEXT frame
        let mut reload_requested = false; // first load will wake this up
        let mut active_view: Option<usize> = None;
        let view_to_start = if start_test.is_empty() { None } else { Some(start_test.clone()) };
        let mut window_pose = Pose::new(Vec3::new(0.4, 1.35, -0.35), Some(Quat::from_angles(0.0, 200.0, 0.0)));
        let mut status = String::from("waiting for plugin");
        let mut copy_counter = 0u32;
        let mut test_step = 0u32;
        let mut fps = 0.0f64;

        SkClosures::new(sk, move |sk, token| {
            let sk_ptr: *mut c_void = (sk as *const Sk).cast_mut().cast();

            // 1 - Drain the background watcher messages
            loop {
                match receiver.try_recv() {
                    Ok(HostMsg::LibChanged) => {
                        if fingerprint(&lib_path) != loaded_fp {
                            reload_requested = true;
                        }
                    }
                    Ok(HostMsg::BuildStarted) => status = "building...".to_string(),
                    Ok(HostMsg::BuildFinished { ok, tail }) => {
                        if ok {
                            status = "build ok".to_string();
                            // In case the build produced a new lib while the
                            // watch thread was busy.
                            if fingerprint(&lib_path) != loaded_fp {
                                reload_requested = true;
                            }
                        } else {
                            status = format!("build FAILED:\n{tail}");
                        }
                    }
                    Err(TryRecvError::Empty) | Err(TryRecvError::Disconnected) => break,
                }
            }

            // 2 - Unload the zombie of the previous frame (dlclose one full
            //     frame after end(), belt and braces against reentrancy)
            if let Some(lib) = zombie.take() {
                drop(lib);
            }

            // 3 - (Re)load the plugin when needed: the NEW plugin is loaded and validated BEFORE the old one is
            //     retired, so a broken build never kills the running session.
            if reload_requested || (plugin_cell.borrow().is_none() && lib_path.exists()) {
                reload_requested = false;
                let previous_name = active_view.and_then(|index| {
                    plugin_cell
                        .borrow()
                        .as_ref()
                        .and_then(|plugin| plugin.views.get(index).map(|view| view.name.clone()))
                });
                Log::info(format!("cargo-run_sk: loading plugin from {}", lib_path.display()));
                let wanted_name = previous_name.or_else(|| view_to_start.clone());
                match load_plugin(Some(sk_ptr), &lib_path, &mut copy_counter) {
                    Ok(new_plugin) => {
                        if let Some(old) = plugin_cell.borrow_mut().take() {
                            old.end();
                            zombie = Some(old.lib); // dlclose next frame
                        }
                        loaded_fp = fingerprint(&lib_path);
                        let selected = wanted_name.as_deref().and_then(|name| find_view(&new_plugin.views, name));
                        active_view = selected.filter(|&index| new_plugin.select(index as u32) == 0);
                        let views = new_plugin.views.len();
                        let selected_name = active_view
                            .map(|index| new_plugin.views[index].name.clone())
                            .unwrap_or_else(|| "none".to_string());
                        *plugin_cell.borrow_mut() = Some(new_plugin);
                        status = format!("{views} views, active: {selected_name}");
                        Log::info(format!("cargo-run_sk: plugin loaded ({status})"));
                    }
                    Err(err) => {
                        Log::err(format!("cargo-run_sk: {err}"));
                        if plugin_cell.borrow().is_none() {
                            status = format!("load failed: {err}");
                        }
                    }
                }
            }

            // 4 - The selector window
            let mut pressed: Option<usize> = None;
            let mut capture = false;
            Ui::window("run_sk").pose(&mut window_pose).size(Vec2::new(0.26, 0.42)).begin();
            Ui::label(format!("{fps:.0} fps")).use_padding(true).draw();
            Ui::label(&status).use_padding(true).draw();
            if Ui::button("Reload").press() {
                reload_requested = true;
            }
            Ui::same_line();
            if Ui::button("Capture").press() {
                capture = true;
            }
            Ui::next_line();
            Ui::hseparator();
            {
                let plugin = plugin_cell.borrow();
                match plugin.as_ref() {
                    Some(plugin) => {
                        for (index, view) in plugin.views.iter().enumerate() {
                            let active = active_view == Some(index);
                            let label = format!(
                                "{}{}{}",
                                if active { "> " } else { "" },
                                view.name,
                                if view.has_screenshot { " (img)" } else { "" }
                            );
                            if Ui::button(label).press() {
                                pressed = Some(index);
                            }
                        }
                    }
                    None => Ui::label("no plugin loaded").use_padding(true).draw(),
                }
            }
            Ui::window_end();

            // 5 - Apply the UI choices
            if let Some(index) = pressed {
                let plugin = plugin_cell.borrow();
                if let Some(plugin) = plugin.as_ref() {
                    active_view = if plugin.select(index as u32) == 0 { Some(index) } else { None };
                }
            }
            if capture {
                let name = active_view
                    .and_then(|index| {
                        plugin_cell
                            .borrow()
                            .as_ref()
                            .and_then(|plugin| plugin.views.get(index).map(|view| view.name.clone()))
                    })
                    .unwrap_or_else(|| "none".to_string());
                capture_screenshot(&name);
            }

            // 6 - Step the plugin (pre-app then post-app steppers, like SkClosures)
            {
                let plugin = plugin_cell.borrow();
                if let Some(plugin) = plugin.as_ref() {
                    let token_ptr: *mut c_void = (token as *const MainThreadToken).cast_mut().cast();
                    plugin.step(sk_ptr, token_ptr);
                }
            }

            // 7 - --test mode: auto-select a view, screenshot then quit
            if test_steps > 0 {
                if test_step == 0 && active_view.is_none() {
                    let plugin = plugin_cell.borrow();
                    if let Some(plugin) = plugin.as_ref()
                        && !plugin.views.is_empty()
                        && plugin.select(0) == 0
                    {
                        active_view = Some(0);
                    }
                }
                test_step += 1;
                if test_step == test_steps {
                    let name = active_view
                        .and_then(|index| {
                            plugin_cell
                                .borrow()
                                .as_ref()
                                .and_then(|plugin| plugin.views.get(index).map(|view| view.name.clone()))
                        })
                        .unwrap_or_else(|| "none".to_string());
                    capture_screenshot(&name);
                } else if test_step > test_steps {
                    sk.quit(None);
                }
            }

            fps = ((1.0 / Time::get_step()) + fps) / 2.0;
        })
        .shutdown(move |_sk| {
            // Properly shut the plugin steppers down before the engine dies.
            if let Some(plugin) = plugin_cell_for_shutdown.borrow_mut().take() {
                plugin.end();
            }
        })
        .run();

        Sk::shutdown();
    }
}
